# Find the seed: largest bottom-right square whose diagonal is entirely non-background. Test on both demos and derive g with the right anchor.
def find_seed(I):
    inp=np.array(I); M=inp.shape[0]
    bg=collections.Counter(int(v) for v in inp.diagonal()).most_common(1)[0][0]
    best=None
    for r in range(M):
        for c in range(M):
            k=1
            while r+k<=M and c+k<=M:
                dv=[int(inp[r+i,c+i]) for i in range(k)]
                if all(v!=bg for v in dv):
                    if (best is None or k>best[2]) and len(set(dv))>=2:
                        best=(r,c,k,dv)
                k+=1
    return best
