# simpler manual extraction
def extract(t):
    out={}
    for m in re.finditer(r'(Demo pair (\d+) (?:input|output)|Test input) \((\d+)x(\d+)\):\n((?:[\d\s]+(?:\n)+){1})',t):
        key,num,_,h,w,m2=m[1],m[2],m[3],m[4],m[5],m[6]
        rows=[r.split() for r in m2.split('\n')[:h]]
        if len(rows)==h and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            g=[[int(x) for x in r] for r in rows]
            # dedupe: only store first time we see this (num,label) combo across whole scan
            out[(num,key)]=g
    return out
